// asserts hostname/IP, then runs each command passed on argv. Password never echoed.
require("dotenv").config();
const { createDecipheriv, scryptSync } = require("node:crypto");
const { PrismaClient } = require("@prisma/client");
const { Client } = require("ssh2");

function deriveKey() {
  return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
  d.setAuthTag(Buffer.from(tagB64, "base64"));
  return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
}
function exec(conn, command, timeoutMs) {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "", stderr = "", settled = false;
      const timer = setTimeout(() => { if (!settled) { settled = true; try { stream.close(); } catch {} reject(new Error("timeout")); } }, timeoutMs);
      stream.on("close", (code) => { if (settled) return; settled = true; clearTimeout(timer); resolve({ code, stdout, stderr }); })
        .on("data", (x) => stdout += x.toString("utf8"))
        .stderr.on("data", (x) => stderr += x.toString("utf8"));
    });
