(async () => {
  const cmds = process.argv.slice(2);
  const p = new PrismaClient();
  const s = await p.server.findUnique({ where: { id: "cmsecmdps0001hlp27ai6mr7c" }, include: { dedicatedIp: true } });
  await p.$disconnect();
  const host = s.dedicatedIp.address;
  const password = decryptSecret(s.rootPasswordEnc);
  const conn = new Client();
  await new Promise((resolve, reject) => {
